// Copies chunks from an async source into a sink.
export async function pump(source, sink, opts = {}) {
  const signal = opts?.signal;
  let written = 0;

  // Helper to swallow cleanup errors and avoid unhandled rejections
  async function safeReturn() {
    try {
      await source.return();
    } catch {}
  }
  async function safeAbort(err) {
    try {
      await sink.abort(err);
    } catch {}
  }

  // Already-aborted fast path: no read/write, cleanup and reject with reason
  if (signal?.aborted) {
    const err = signal.reason;
    await safeReturn();
    await safeAbort(err);
    throw err;
  }

  let abortListener = null;
  let abortPromise = null;
  if (signal) {
    abortPromise = new Promise((_, reject) => {
      const onAbort = () => reject(signal.reason);
      abortListener = { signal, onAbort };
      signal.addEventListener('abort', onAbort, { once: true });
    });
  }

  function cleanupAbortListener() {
    if (abortListener) {
      try {
        abortListener.signal.removeEventListener('abort', abortListener.onAbort);
      } catch {}
      abortListener = null;
    }
  }

  try {
    while (true) {
      // --- source.next() with abort racing ---
      let nextP;
      try {
        nextP = source.next();
      } catch (e) {
        // synchronous throw from next()
        throw e;
      }

      let result;
      try {
        if (abortPromise) {
          result = await Promise.race([nextP, abortPromise]);
        } else {
          result = await nextP;
        }
      } catch (err) {
        // If abort won, nextP may still settle later -> prevent unhandled rejection
        if (abortPromise) {
          Promise.resolve(nextP).catch(() => {});
        }
        throw err;
      }

      if (result.done) break;

      // Abort could have happened between next() and write()
      if (signal?.aborted) {
        throw signal.reason;
      }

      // --- sink.write() with abort racing ---
      let writeP;
      try {
        writeP = sink.write(result.value);
      } catch (e) {
        throw e;
      }

      try {
        if (abortPromise) {
          await Promise.race([writeP, abortPromise]);
        } else {
          await writeP;
        }
      } catch (err) {
        if (abortPromise) {
          Promise.resolve(writeP).catch(() => {});
        }
        throw err;
      }

      written++;
    }

    // Success path
    cleanupAbortListener();
    try {
      await sink.close();
    } catch (closeErr) {
      // Close failure is treated as failure: cleanup and rethrow original close error
      await safeReturn();
      await safeAbort(closeErr);
      throw closeErr;
    }
    return { written };
  } catch (originalErr) {
    cleanupAbortListener();
    await safeReturn();
    await safeAbort(originalErr);
    throw originalErr;
  }
}

