export async function pump(source, sink, opts = {}) {
  const signal = opts.signal;
  let written = 0;

  const throwIfAborted = () => {
    if (signal?.aborted) {
      throw signal.reason;
    }
  };

  const withSignal = (promise) => {
    if (!signal) return promise;
    if (signal.aborted) {
      return Promise.reject(signal.reason);
    }
    return new Promise((resolve, reject) => {
      const onAbort = () => {
        reject(signal.reason);
      };
      signal.addEventListener('abort', onAbort, { once: true });
      promise.then(
        (v) => {
          signal.removeEventListener('abort', onAbort);
          resolve(v);
        },
        (e) => {
          signal.removeEventListener('abort', onAbort);
          reject(e);
        }
      );
    });
  };

  const safeReturn = async () => {
    try {
      await source.return();
    } catch {}
  };

  const safeAbort = async (err) => {
    try {
      await sink.abort(err);
    } catch {}
  };

  try {
    throwIfAborted();

    while (true) {
      let result;
      try {
        let p;
        try {
          p = Promise.resolve(source.next());
        } catch (e) {
          p = Promise.reject(e);
        }
        result = await withSignal(p);
      } catch (e) {
        throw e;
      }

      if (result.done) break;

      throwIfAborted();

      try {
        let p;
        try {
          p = Promise.resolve(sink.write(result.value));
        } catch (e) {
          p = Promise.reject(e);
        }
        await withSignal(p);
      } catch (e) {
        throw e;
      }

      written++;
      throwIfAborted();
    }

    throwIfAborted();

    try {
      await sink.close();
    } catch (e) {
      throw e;
    }

    return { written };
  } catch (original) {
    try {
      await safeReturn();
    } catch {}
    try {
      await safeAbort(original);
    } catch {}
    throw original;
  }
}

