export async function pump(source, sink, opts = {}) {
  const signal = opts.signal;
  let written = 0;
  let returned = false;
  let aborted = false;

  async function doReturn() {
    if (returned) return;
    returned = true;
    try {
      const r = source.return();
      await r;
    } catch {}
  }

  async function doAbort(err) {
    if (aborted) return;
    aborted = true;
    try {
      const r = sink.abort(err);
      await r;
    } catch {}
  }

  let abortListener;
  let abortPromise;
  if (signal) {
    if (signal.aborted) {
      const reason = signal.reason;
      await doReturn();
      await doAbort(reason);
      throw reason;
    }
    abortPromise = new Promise((_, reject) => {
      abortListener = () => reject(signal.reason);
      signal.addEventListener('abort', abortListener, { once: true });
    });
    // Prevent unhandled rejection if abort fires after success
    abortPromise.catch(() => {});
  }

  async function raceWithAbort(p) {
    if (!signal) {
      return await p;
    }
    try {
      return await Promise.race([p, abortPromise]);
    } catch (e) {
      // If abort won, p may later reject; swallow to avoid unhandled
      p.catch(() => {});
      throw e;
    }
  }

  try {
    while (true) {
      if (signal?.aborted) throw signal.reason;

      let nextRes;
      try {
        let np;
        try {
          np = source.next();
        } catch (err) {
          np = Promise.reject(err);
        }
        np = Promise.resolve(np);
        nextRes = await raceWithAbort(np);
      } catch (err) {
        throw err;
      }

      if (nextRes.done) break;

      if (signal?.aborted) throw signal.reason;

      try {
        let wp;
        try {
          wp = sink.write(nextRes.value);
        } catch (err) {
          wp = Promise.reject(err);
        }
        wp = Promise.resolve(wp);
        await raceWithAbort(wp);
      } catch (err) {
        throw err;
      }

      written++;
    }

    if (signal?.aborted) throw signal.reason;

    try {
      let cp;
      try {
        cp = sink.close();
      } catch (err) {
        cp = Promise.reject(err);
      }
      await Promise.resolve(cp);
    } catch (err) {
      throw err;
    }

    return { written };
  } catch (orig) {
    await doReturn();
    await doAbort(orig);
    throw orig;
  } finally {
    if (signal && abortListener) {
      signal.removeEventListener('abort', abortListener);
